\label{thm:local-linearization}
Assume Condition~\ref{cond:A} holds with $q_0>q_H$. Fix
$0<T_0<T<\infty$, $q_H<q\le q_0$, and $1\le p\le q/2$.  
\begin{itemize}
\item[(i)] Fix $0<\delta<\delta_t(q)$. There exist $C<\infty$ and
$\varepsilon_0>0$ such that
\begin{equation}\label{t:eq:main-moment}
 \sup_{T_0\le t\le T}\sup_{x\in\mathbb R}
 \lambda(x)^{1/q}\left\|R^{\mathrm t}(t,x,\varepsilon)\right\|_{p}
 \le C|\varepsilon|^{H/2+\delta},\qquad 0<|\varepsilon|\le \varepsilon_0.
\end{equation} \item[(ii)]

Fix $0<\delta<\delta_x^*$. There exist $C<\infty$ and
$\varepsilon_0>0$ such that
\begin{equation}\label{eq:main}
 \sup_{T_0\le t\le T}\sup_{x\in\mathbb R}
 \lambda(x)^{1/q}\left\|R^{\mathrm x}(t,x,\varepsilon)\right\|_{p}
 \le C|\varepsilon|^{H+\delta},\qquad 0<|\varepsilon|\le \varepsilon_0.
\end{equation}

\end{itemize}

\label{thm:oscillations}
Assume that Condition~\ref{cond:A} holds with $q_0>q_H$.
For each fixed $(t,x)\in(0,\infty)\times\mathbb R$, the following
Khinchin and Chung LILs hold almost surely.
\begin{itemize}
\item[(i)] If $\delta_{x,\mathrm{pw}}>0$, then
\begin{align}
 \limsup_{h\downarrow0}
 \frac{u(t,x+h)-u(t,x)}
      {h^H\sqrt{2\log\log(1/h)}}
 =&\, \frac{|\sigma(u(t,x))|}{\sqrt2},
 \label{eq:spatial-lil}\\
 \liminf_{r\downarrow0}\sup_{0\le h\le r}
 \frac{ |u(t,x+h)-u(t,x)|}
      {(r/\log\log(1/r))^H}
 =&\, \frac{b_H^H}{\sqrt2}|\sigma(u(t,x))|.
 \label{eq:spatial-chung}
\end{align}

\item[(ii)] If $\delta_{t,\mathrm{pw}}>0$, then
\begin{align}
 \limsup_{h\downarrow0}
 \frac{u(t+h,x)-u(t,x)}
      {h^{H/2}\sqrt{2\log\log(1/h)}}
 =&\, \gamma_H|\sigma(u(t,x))|,
 \label{eq:temporal-lil}\\
 \liminf_{r\downarrow0}\sup_{0\le h\le r}
 \frac{ |u(t+h,x)-u(t,x)|}
      {(r/\log\log(1/r))^{H/2}}
 =&\, \gamma_H b_{H/2}^{H/2}|\sigma(u(t,x))|.
 \label{eq:temporal-chung}
\end{align}
\end{itemize}

\label{thm:uniform-moduli}
Assume that Condition~\ref{cond:A} holds with $q_0>q_H$.
\begin{itemize}
\item[(i)] Assume $\delta_{x,\mathrm{pw}}>0$. For each fixed $t>0$,
with probability one, every
nondegenerate compact interval $J\subset\mathbb R$ satisfies
\begin{equation}\label{eq:spatial-modulus}
 \lim_{r\downarrow0}\sup_{\substack{x,y\in J\\ |y-x|\le r}}
 \frac{ 
       |u(t,y)-u(t,x)|}
      {r^H\sqrt{2\log(1/r)}}
 =\frac1{\sqrt2}\max_{y\in J}|\sigma(u(t,y))|.
\end{equation}

\item[(ii)] Assume $\delta_{t,\mathrm{pw}}>0$. For each fixed $x\in\mathbb R$,
with probability one, every
nondegenerate compact interval $I\subset(0,\infty)$ satisfies
\begin{equation}\label{eq:temporal-modulus}
 \lim_{r\downarrow0}\sup_{\substack{s,t\in I\\ |t-s|\le r}}
 \frac{ 
       |u(t,x)-u(s,x)|}
      {r^{H/2}\sqrt{2\log(1/r)}}
 =\gamma_H\max_{s\in I}|\sigma(u(s,x))|.
\end{equation}
\end{itemize}

\label{prop:bdg}
Let $f\in\Lambda_H$. Then, for every $p\ge2$,
\begin{equation}\label{eq:BDG}
\left\|
\int_0^t\int_{\mathbb R}f(s,y)\,W(\mathrm d s,\mathrm d y)
\right\|_{p}
\le
\sqrt{4p}\,c
\left(
\int_0^t\int_{\mathbb R}
\bigl[\mathcal N_{1/2-H,p}f(s,y)\bigr]^2
\,\mathrm d y\,\mathrm d s
\right)^{1/2},
\end{equation}
where $c$ is a constant depending only on $H$.

\label{lem:initial-smoothing}
\textup{(i)} For the weight function $\lambda$
defined by \eqref{eq weight}, we have
\begin{equation}\label{eq:weight-ratio}
\frac{\lambda(x)}{\lambda(y)}
\le C_H(1+|x-y|)^{2(1-H)},
\qquad x,y\in\mathbb R.
\end{equation}
\textup{(ii)} Let $0<T_0<T<\infty$,
$2\le q<\infty$, $1\le p\le q$, and $j=0,1,2$.
If $f\in L^q_\lambda(\Omega\times\mathbb R)$, then
\begin{equation}\label{eq:msmooth}
\sup_{T_0\le t\le T}\sup_{x\in\mathbb R}
\lambda(x)^{1/q}
\left\|\partial_x^j(G_t*f)(x)\right\|_p
\le
C_{T_0,T,q,H,j}
\left\|f\right\|_{L^q_\lambda(\Omega\times\mathbb R)}.
\end{equation}

\label{prop:solution}
Assume Condition~\ref{cond:A} holds. For every $T>0$,
there exists a weak solution $u$ to \eqref{eq:SHE}
on $[0,T]\times\mathbb R$ such that
$$
\left\|u\right\|_{\mathcal Z^{q_0}_{\lambda,T}}<\infty.
$$
Moreover, the following estimates hold for any such weak solution.
\begin{itemize}
\item[(i)]
For every $0<T_0<T<\infty$,
$\frac{6}{4H-1}<q\le q_0$, and $1\le p\le q$,
we have
\begin{equation}\label{eq:umom}
\sup_{T_0\le t\le T}\sup_{x\in\mathbb R}
\lambda(x)^{1/q}\left\|u(t,x)\right\|_p<\infty.
\end{equation}
\item[(ii)]
If, in addition, $q_H<q\le q_0$, then
for $1\le p\le q$,
\begin{equation}\label{eq:ufrac}
\sup_{T_0\le t\le T}\sup_{x\in\mathbb R}
\lambda(x)^{1/q}
\mathcal N_{1/2-H,p}u(t,x)<\infty.
\end{equation}
\end{itemize}

\label{lem:U-increment}
For every finite \(p\ge1\),  there exists a constant $C_p>0$ such that for every 
 $s,t\ge0$ and  $x,y\in\mathbb R$,
\begin{equation}\label{eq:U-increment-Lp}
 \left\|U(t,x)-U(s,y)\right\|_{p}
 \le C_p\bigl(|t-s|^{H/2}+|x-y|^H\bigr).
\end{equation}

\label{prop:regularity}
Fix $0<T_0<T<\infty$. For every $q_H<q\le q_0$ and $1\le p\le q$, there exists a constant  $C>0$ such that
\begin{equation}\label{eq:exact-holder}
\left\|u(t,x)-u(s,y)\right\|_{p}
\le
C\left(\lambda(x)^{-1/q}+\lambda(y)^{-1/q}\right)
\left(|t-s|^{H/2}+|x-y|^H\right),
\end{equation}
for all $s,t\in[T_0,T]$ and $x,y\in\mathbb R$.

\label{lem:freeze}
Let  $q_H<q\le q_0$ and $2\le p\le q/2$.
There exists a constant $C<\infty$ such that
the following estimates hold uniformly for $t\in[T_0,T]$,
$x\in\mathbb R$, $0<\rho<1\wedge(T_0/2)$, and $0<\varepsilon\le1$:
\begin{itemize}
\item[(i)]
\begin{equation}\label{eq:freeze}
\lambda(x)^{1/q}
\left\|J_{\mathrm n}-\widetilde J_{\mathrm n}\right\|_{p}
\le
C\bigl(
\varepsilon^H\rho^{H/2}
+\varepsilon^{2H}
+\varepsilon^{1/2}
\bigr).
\end{equation}
\item[(ii)]
\begin{equation}\label{eq:freeze-coeff}
\lambda(x)^{1/q}
\left\|[\sigma(u(t-\rho,x))-\sigma(u(t,x))]L_{\mathrm n}\right\|_{p}
\le C\varepsilon^H\rho^{H/2}.
\end{equation}
\end{itemize}

\label{lemma:pathwise}
Assume Condition~\ref{cond:A} holds with $q_0>q_H$.
\begin{itemize}
\item[(i)] Fix $x\in\mathbb R$. With probability one, for every compact interval                                            
$I\subset(0,\infty)$ and every $0<\delta_t<\delta_{t,\mathrm{pw}}$,
\begin{equation}\label{eq:temporal-pathwise}
 \sup_{\substack{s,t\in I\\|t-s|\le r}}
 |R^{\mathrm t}(s,x,t-s)|=o\left(r^{H/2+\delta_t}\right),\qquad r\downarrow0.
\end{equation}  
\item[(ii)]   Fix $t>0$. With probability one, for every compact interval
$J\subset\mathbb R$ and every $0<\delta_x<\delta_{x,\mathrm{pw}}$,
\begin{equation}\label{eq:spatial-pathwise}
 \sup_{\substack{x,y\in J\\|y-x|\le r}}
 |R^{\mathrm x}(t,x,y-x)|=o\left(r^{H+\delta_x}\right),\qquad r\downarrow0.
\end{equation}

\end{itemize}

\label{lem:completion}  
\begin{itemize}
\item[(i)] (\cite[Theorem~1(b)]{WangZhang2021}) For each fixed $t>0$, there exist a standard two-sided fBm
$\{B_t^H(y):y\in\mathbb R\}$ and a centered Gaussian process
$\{S_t(y):y\in\mathbb R\}$, with $S_t(0)=0$ and
$C^\infty(\mathbb R)$ sample paths, such that 
\begin{equation}\label{eq:completion}
 U(t,y)-U(t,0)
 =\frac1{\sqrt2}B_t^H(y)-S_t(y),
 \qquad y\in\mathbb R.
\end{equation}

\item[(ii)] (\cite[Lemma~6.1]{Qian2026})
For each fixed $x\in\mathbb R$, there exists a centered Gaussian process
$\{S(t): t\ge0\}$, independent of $\{U(t,x): t\ge0\}$, such that the process
\begin{equation}\label{eq:completion-time}
 B^{H/2}(t):=\gamma_H^{-1}[U(t,x)+S(t)],
 \qquad t\ge0,
\end{equation}
is a standard fBm. Moreover, $S$ admits a version with
$C^\infty(0,\infty)$ sample paths.
\end{itemize}

\label{lem:fbm-laws} Let $B^\alpha$ be a standard fBm with $0<\alpha<1$,
defined on either $[0,\infty)$ or $\mathbb R$. 
\begin{itemize}
\item[(i)] \emph{(Khinchin-type LIL).}
For each fixed $z_0$ in the parameter domain of $B^\alpha$,

\begin{equation}\label{eq:fbm-khinchin}
 \limsup_{h\downarrow0}
 \frac{B^\alpha(z_0+h)-B^\alpha(z_0)}
      {h^\alpha\sqrt{2\log\log(1/h)}}
 =1 \ \ \ \text{a.s.}
\end{equation}

\item[(ii)] \emph{(Chung-type  LIL).} 
For each fixed $z_0$ in the parameter domain of $B^\alpha$,
\begin{equation}\label{eq:fbm-chung}
 \liminf_{r\downarrow0}\sup_{0\le h\le r}
 \frac{ 
       |B^\alpha(z_0+h)-B^\alpha(z_0)|}
      {(r/\log\log(1/r))^\alpha}
 =b_\alpha^\alpha  \ \ \ \text{a.s.,}
\end{equation}
where $b_\alpha$ is defined in \eqref{eq:fbm-small-constant}.

  \item[(iii)] \emph{(Exact uniform modulus of continuity).}
For each nondegenerate compact interval $I$, 
 \[
 \lim_{r\downarrow0}\sup_{\substack{s,t\in I\\ |t-s|\le r}}
 \frac{          |B^\alpha(t)-B^\alpha(s)|}
      {r^\alpha\sqrt{2\log(1/r)}}
 =1   \ \ \ \text{a.s.}
\]
\end{itemize}

\label{rem:normalized-moduli}
Lemma~\ref{lemma:pathwise}, together with
Lemmas~\ref{lem:completion} and \ref{lem:fbm-laws}(iii), also yields
the following coefficient-normalized uniform moduli of continuity,
analogous to those obtained by Hu and
Lee~\cite[Theorem~1.2]{HuLee2026}. More precisely,
if $\delta_{x,\mathrm{pw}}>0$, then for each fixed $t>0$, 
every nondegenerate compact interval $J\subset\mathbb R$ with
$$
 \inf_{x\in J}|\sigma(u(t,x))|>0
$$
satisfies
\begin{align}\label{eq Lee1}
 \lim_{r\downarrow0}
 \sup_{\substack{x,y\in J\\ |y-x|\le r}}
 \frac{|u(t,y)-u(t,x)|}
 {r^H\sqrt{2\log(1/r)}\,|\sigma(u(t,x))|}
 =\frac1{\sqrt2} \ \ \ \text{a.s.}
\end{align}
Similarly, if $\delta_{t,\mathrm{pw}}>0$, then for each fixed $x\in\mathbb R$,  every nondegenerate compact interval
$I\subset(0,\infty)$ with
$$
 \inf_{s\in I}|\sigma(u(s,x))|>0
$$
satisfies
\begin{align}\label{eq Lee2}
 \lim_{r\downarrow0}
 \sup_{\substack{s,t\in I\\ |t-s|\le r}}
 \frac{|u(t,x)-u(s,x)|}
 {r^{H/2}\sqrt{2\log(1/r)}\,|\sigma(u(s,x))|}
 =\gamma_H \ \ \ \text{a.s.}
\end{align}




Since $|\sigma(u)|$ is bounded away from zero on each such interval,
the remainders and smooth Gaussian corrections remain uniformly
negligible under the corresponding normalizations.
Both assertions therefore follow from the exact uniform moduli
of continuity of fBm.
The lower bound in Theorem~\ref{thm:uniform-moduli}, however,
requires an additional localization argument near points where
$|\sigma(u)|$ is close to its maximum on the compact interval.
We present this argument in the next subsection.

\label{lem:schwartz}
Let $0<H<1/2$. For every Schwartz function $f$ on $\mathbb R$,
\begin{equation}\label{eq:schwartz}
Q_Hf(z)
:=
\int_\mathbb R |f(z+h)-f(z)|^2|h|^{2H-2}\mathrm d h
\le
C_{f,H}(1+|z|)^{2H-2},
\quad z\in\mathbb R.
\end{equation}

\label{t:lem:integrated}
Let $q_H<q\le q_0$ and $0<\beta<1$.  There exists a constant $C>0$ such that the following estimates
hold uniformly for $x\in\mathbb R$ and all sufficiently small
$\varepsilon>0$.  
\begin{itemize}
\item[(i)]
\begin{equation}\label{t:eq:integrated-remote}
\begin{aligned}
&\int_{\varepsilon^\beta}^T\int_{\mathbb R^2}
|D_{r+\varepsilon}(x-y,h)-D_r(x-y,h)|^2
|h|^{2H-2}\lambda(y)^{-2/q}
\mathrm d y\mathrm d h\mathrm d r\\
\le&\,
C\lambda(x)^{-2/q}\varepsilon^{2+\beta(H-2)}.
\end{aligned}
\end{equation}

\item[(ii)]
\begin{equation}\label{t:eq:integrated-L2}
\int_0^T\int_\mathbb R
|G_{r+\varepsilon}(x-y)-G_r(x-y)|^2
\lambda(y)^{-2/q}\mathrm d y\mathrm d r
\le
C\lambda(x)^{-2/q}\varepsilon^{1/2}.
\end{equation}

\item[(iii)]
If
$$
0\le\vartheta<\frac{1-2H-a_q}{4},
$$
then
\begin{equation}\label{t:eq:integrated-weighted}
\begin{aligned}
&\int_0^{\varepsilon^\beta}\int_{\mathbb R^2}
\bigl(
|D_r(x-y,h)|^2
+
|D_{r+\varepsilon}(x-y,h)|^2
\bigr)
|h|^{2H-2}|x-y|^{4\vartheta}
\lambda(y)^{-2/q}
\mathrm d y\mathrm d h\mathrm d r\\
\le&\,
C\lambda(x)^{-2/q}\varepsilon^{\beta(H+2\vartheta)}.
\end{aligned}
\end{equation}

\end{itemize}

\label{lem:energy}
For every $\varepsilon>0$,
\begin{equation}\label{eq:energy}
\int_0^\infty\int_{\mathbb R^2}
|D_r(z+h,\varepsilon)-D_r(z,\varepsilon)|^2|h|^{2H-2}
\mathrm d h\mathrm d z\mathrm d r
=
\frac{\varepsilon^{2H}}{H(1-2H)}.
\end{equation}

\label{lem:tails}
Let $0<\gamma<1-H$ and $R\ge1$. The following estimates hold.
\begin{itemize}

\item[(i)]
\begin{equation}\label{eq:localmoment}
\int_{|w|\le R}|w|^{2\gamma}F_H(w)\mathrm d w
\le
C
\begin{cases}
1+R^{2\gamma+2H-1},
& 2\gamma+2H-1>0,\\
1+\log R,
& 2\gamma+2H-1=0,\\
1,
& 2\gamma+2H-1<0.
\end{cases}
\end{equation}

\item[(ii)]
For every $0\le a<1-2H$,
\begin{equation}\label{eq:weightedtail}
\int_{|w|>R}(1+|w|)^aF_H(w)\mathrm d w
\le
CR^{a+2H-1}.
\end{equation}

\end{itemize}

\label{lem:weightedenergy}
Let $0\le a<1-2H$ and $0<\varepsilon\le1$. There exists a constant
$C>0$ such that
\begin{equation}\label{eq:wenergy}
\int_0^\infty\int_{\mathbb R^2}
|D_r(z+h,\varepsilon)-D_r(z,\varepsilon)|^2
|h|^{2H-2}(1+|z|)^a
\mathrm d h\mathrm d z\mathrm d r
\le
C\varepsilon^{2H}.
\end{equation}
Moreover, for every $0<\gamma<1-H$,
\begin{equation}\label{eq:wlocalenergy}
\begin{aligned}
&\int_0^\infty\int_{\mathbb R^2}
|D_r(z+h,\varepsilon)-D_r(z,\varepsilon)|^2
|h|^{2H-2}(1+|z|)^a
(|z|^{2\gamma}\wedge1)
\mathrm d h\mathrm d z\mathrm d r\\
\le&\,
C
\begin{cases}
\varepsilon^{2H+2\gamma}+\varepsilon,
& \gamma\ne\frac12-H,\\[1mm]
\varepsilon(1+|\log\varepsilon|),
& \gamma=\frac12-H.
\end{cases}
\end{aligned}
\end{equation}
